"""生成可离线浏览的设计图册；设计稿不依赖生产代码或后端。"""
from pathlib import Path
import base64
import json
import re
import html

ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent
PAGES = []

def e(s): return html.escape(str(s))
def photo(name):
    data = base64.b64encode((ROOT / 'miniapp/assets/venues' / name).read_bytes()).decode()
    return 'data:image/jpeg;base64,' + data
PHOTOS = {i: photo(f'venue-{i}.jpg') for i in (1, 2, 3)}
