def icon(name, size=18):
    return f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{PATHS[name]}</svg>'
def btn(text, primary=False, go='', ico='', cls=''):
    return f'<button class="btn {"primary" if primary else ""} {cls}" {f"data-go={e(go)}" if go else "data-demo"}>{icon(ico,16) if ico else ""}{e(text)}</button>'
def badge(text, tone='green'): return f'<span class="badge {tone}">{e(text)}</span>'
def field(label, value='', kind='text', options=None):
    if options is not None:
        control = '<select>' + ''.join(f'<option>{e(v)}</option>' for v in options) + '</select>'
    elif kind == 'textarea': control = f'<textarea rows="4">{e(value)}</textarea>'
    else: control = f'<input type="{kind}" value="{e(value)}" aria-label="{e(label)}">'
    return f'<label class="field"><span>{e(label)}</span>{control}</label>'
def panel(title, content, sub='', right=''):
    return f'<section class="panel"><header class="panel-head"><div><h2>{e(title)}</h2>{f"<p>{e(sub)}</p>" if sub else ""}</div>{right}</header>{content}</section>'
def table(headers, rows, title='', sub=''):
    body = '<div class="table-wrap"><table><thead><tr>' + ''.join(f'<th>{e(h)}</th>' for h in headers) + '</tr></thead><tbody>'
    body += ''.join('<tr>' + ''.join(f'<td>{v}</td>' for v in r) + '</tr>' for r in rows)
    body += '</tbody></table></div>'
    body += f'<div class="pagination"><span>共 {len(rows)} 条示例记录</span><div>{btn("上一页")}{btn("1",cls="page-active")}{btn("下一页")}</div></div>'
    return panel(title, body, sub) if title else body

def filters(items): return '<div class="filters">' + ''.join(items) + '</div>'
def tabs(items, selected=0):
    return '<div class="tabs">' + ''.join(f'<button class="{"selected" if i==selected else ""}" {f"data-go={slug}" if slug else "data-tab"}>{e(label)}</button>' for i,(label,slug) in enumerate(items)) + '</div>'
def facts(items):
    return '<dl class="facts">' + ''.join(f'<div><dt>{e(k)}</dt><dd>{v}</dd></div>' for k,v in items) + '</dl>'
def metric(items):
    return f'<div class="metrics" style="--metric-count:{len(items)}">' + ''.join(f'<div><label>{e(k)}</label><strong>{e(v)}</strong><small>{e(s)}</small></div>' for k,v,s in items) + '</div>'
def notice(text, tone='info'): return f'<div class="notice {tone}">{icon("shield",16)}<span>{e(text)}</span></div>'
def img(i=1, cls='', alt='演示场馆图片'): return f'<img class="{cls}" src="{PHOTOS[i]}" alt="{e(alt)}">'
def add(slug, title, platform, route, source, group, body, desc='', actions='', extra=False, **meta):
    PAGES.append(dict(id=slug,title=title,platform=platform,route=route,source=source,group=group,body=body,desc=desc,actions=actions,extra=extra,**meta))

