def qr():
    import random
    random.seed(43)
    cells=[]
    for y in range(29):
        for x in range(29):
            if ((x<8 and y<8) or (x>20 and y<8) or (x<8 and y>20)): continue
            if random.random()>.53: cells.append(f'<rect x="{x+3}" y="{y+3}" width="1" height="1"/>')
    for x,y in [(3,3),(25,3),(3,25)]:
        cells.append(f'<rect x="{x}" y="{y}" width="7" height="7"/><rect x="{x+1}" y="{y+1}" width="5" height="5" fill="white"/><rect x="{x+2}" y="{y+2}" width="3" height="3"/>')
    return '<svg class="qr" viewBox="0 0 35 35" role="img" aria-label="示例二维码，不可用于业务扫码"><rect width="35" height="35" fill="white"/><g fill="#243936">'+''.join(cells)+'</g></svg>'

def admin_page(p):
    if p.get('login'): return p['body']
    groups=PLATFORM_NAV if p.get('scope')=='platform' else VENUE_NAV
    nav=''
    for label,items in groups:
        nav+=f'<div><div class="group-title">{label}</div>'
        for slug,ico,text in items:
            active = slug==p.get('parent',p['id'])
            nav+=f'<a href="#" data-go="{slug}" class="nav {"active" if active else ""}">{icon(ico)}<span>{text}</span>{"<i></i>" if active else ""}</a>'
        nav+='</div>'
    who = '平台管理员' if p.get('scope')=='platform' else '场馆超级管理员'
    venue = '约场平台' if p.get('scope')=='platform' else '青羽羽毛球馆'
    return f'''<aside class="sidebar"><div class="brand"><div class="brand-symbol">{icon('court',26)}</div><div><strong>约场</strong><small>场馆运营管理</small></div></div>{nav}<div class="account"><div class="avatar">{ '林' if who=='平台管理员' else '周'}</div><div>{'林管理员' if who=='平台管理员' else '周店长'}<small>{who}</small></div>{icon('exit',16)}</div></aside><main class="admin-main"><header class="topbar"><div class="venue-switch">{venue}{icon('chevron',14)}</div><div class="topright"><span>{'平台工作台' if who=='平台管理员' else '郑州 · 金水区'}</span><span class="live"><i></i>{'平台管理' if who=='平台管理员' else '营业中'}</span>{icon('bell',19)}</div></header><div class="a-body"><header class="heading"><div><h1>{p['title']}</h1><p>{p['desc'] or '2026 年 10 月 14 日，星期三'}</p></div><div class="actions">{p['actions']}</div></header>{p['body']}<footer class="board-watermark"><span>约场 · 场边工作台</span><span>设计示例，所有数据均为演示</span></footer></div></main>'''

def mobile_page(p):
    tab=p.get('tab')
    nav=''
    if tab:
        nav='<nav class="m-bottom" aria-label="底部导航">'+''.join(f'<a href="#" data-go="{slug}" class="{"active" if slug==tab else ""}">{icon(ico,21)}<span>{text}</span></a>' for slug,ico,text in MINI_TABS)+'</nav>'
    head=f'<header class="m-header"><button data-go="{p.get("back","m-mine")}" aria-label="返回">{icon("chevron",19)}</button><span>{p.get("navtitle",p["title"])}</span><span style="width:30px"></span></header>' if not tab else ''
    action=f'<div class="m-footer-action">{p["actions"]}</div>' if p['actions'] else ''
    return f'<main class="mobile">{head}<div class="m-content">{p["body"]}</div>{action}{nav}</main>'

def a(slug,title,path,view,body,desc='',actions='',platform=False,group='场馆运营',**kw):
    add('a-'+slug,title,'admin',path,'admin-web/src/views/'+view+'.vue',group,body,desc,actions,scope='platform' if platform else 'venue',**kw)

