PLATFORM_REPORT_VIEWS=[('operations','经营汇总'),('utilization','时段分析'),('member-operations','会员经营'),('service-fees','月度结算')]

def report_body(view,plat=False):
    prefix='a-platform-report-' if plat else 'a-report-'
    views=PLATFORM_REPORT_VIEWS if plat else REPORT_VIEWS
    tab=tabs([(label,('a-platform-reports' if plat else 'a-reports') if v=='operations' else prefix+v) for v,label in views],next(i for i,(v,l) in enumerate(views) if v==view))
    controls=([field('场馆',options=['全部场馆']+venue_names)] if plat and view!='member-operations' else [])
    controls += [field('月份','2026-10','month')] if view=='service-fees' else [field('开始日期','2026-10-08','date'),field('结束日期','2026-10-14','date')]
    if view=='utilization': controls += [field('运动',options=['全部运动','羽毛球'])]
    controls += [btn('查询',True,ico='search')]
    if view in ['bookings','member-flows','receipts']: controls += [btn('导出 Excel',ico='download')]
    body=tab+filters(controls)
    if view=='operations':
        body+=metric([('线上预约经营金额','¥12,480','按场次日期'),('线下登记经营金额','¥3,260','独立登记口径'),('场地利用率','68%','按分钟计算'),('充值实付流入','¥5,800','按成功日期')])
        body+=panel('经营趋势',trend,'经营金额按场次日期统计；充值与退款不混入经营金额')
